#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Buffs;
using PVZEngine.Definitions;

namespace MVZ2.GameContent.Buffs.Entities
{

    [AutoBuffDefinition(VanillaBuffNames.Entity.teleporterTeleportDown)]
    public class TeleporterTeleportDownBuff : TeleporterBuff
    {
        public TeleporterTeleportDownBuff(string nsp, string name) : base(nsp, name)
        {
        }

        protected override void OnFinished(Buff buff)
        {
            base.OnFinished(buff);
            buff.GetEntity()?.DestroyConflictGridEntities();
        }
    }
}
